def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def pos(val, default=(0, 0)):
        if isinstance(val, (list, tuple)) and len(val) >= 2:
            return val[0], val[1]
        return default

    def step_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def step_away(a, b):
        return [sgn(a[0] - b[0]), sgn(a[1] - b[1])]

    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)
    env = observation.get("environment_name") or "resource_collection"

    if env == "pursuit_evasion":
        role = observation.get("self_role") or "pursuer"
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        gw = observation.get("grid_width")
        gh = observation.get("grid_height")
        corners = [(0, 0)]
        if isinstance(gh, int) and gh > 0:
            corners.append((0, gh - 1))
        if isinstance(gw, int) and gw > 0:
            corners.append((gw - 1, 0))
        if isinstance(gw, int) and gw > 0 and isinstance(gh, int) and gh > 0:
            corners.append((gw - 1, gh - 1))
        target = max(corners, key=lambda p: manhattan(p, opp_pos))
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        best = None
        best_score = None
        for item in targets:
            tx, ty = pos(item, None) if item is not None else (None, None)
            if tx is None:
                continue
            score = manhattan((tx, ty), self_pos) - manhattan((tx, ty), opp_pos) * 0.25
            if best_score is None or score < best_score:
                best_score = score
                best = (tx, ty)
        if best is None:
            return step_away(self_pos, opp_pos)
        return step_toward(self_pos, best)

    resources = observation.get("resources") or []
    best = None
    best_score = None
    for item in resources:
        rx, ry = pos(item, None) if item is not None else (None, None)
        if rx is None:
            continue
        score = manhattan((rx, ry), self_pos) - manhattan((rx, ry), opp_pos) * 0.35
        if best_score is None or score < best_score:
            best_score = score
            best = (rx, ry)

    if best is None:
        return step_away(self_pos, opp_pos)

    # If the opponent is closer to the resource, bias toward safer movement.
    if manhattan(best, opp_pos) <= manhattan(best, self_pos):
        away = step_away(self_pos, opp_pos)
        if away != [0, 0]:
            return away
    return step_toward(self_pos, best)

